<input type="hidden" name="is_active" value="{{ old('is_active', ($contact?->is_active ?? true) ? '1' : '0') }}">
<div class="grid two-col"><div class="grid"><label>Competition name<input name="name" value="{{ old('name', $contact?->name) }}" required></label><label>Code<input name="code" value="{{ old('code', $contact?->code) }}" maxlength="50" placeholder="e.g. PDC"><span class="muted">Shown beneath the competition name.</span></label>@if($contact?->logo_path)<img class="entity-logo" src="{{ $contact->logoUrl() }}" alt="{{ $contact->name }} logo">@endif<label>Competition logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"><span class="muted">JPG, PNG or WebP. The full logo will be shown without cropping.</span></label></div><div class="grid"><label>Internal notes<textarea name="notes" style="min-height:120px">{{ old('notes', $contact?->notes) }}</textarea></label></div></div>

