@foreach($staffRows as $index => $person)<div class="card card-pad competition-staff-row" style="background:var(--surface-subtle, #f8fafc)"><div class="toolbar"><strong class="competition-staff-number">Staff member {{ $loop->iteration }}</strong><button class="button secondary remove-competition-staff" type="button">Remove</button></div><div class="grid two-col"><label>Name<input name="staff[{{ $index }}][name]" value="{{ $person['name'] ?? '' }}" maxlength="255" required></label><label>Role / position<input name="staff[{{ $index }}][role]" value="{{ $person['role'] ?? '' }}" maxlength="255" placeholder="e.g. Competition director"></label><label>Email addresses<input name="staff[{{ $index }}][emails]" value="{{ $person['emails'] ?? '' }}" maxlength="2000" placeholder="name@example.com, accounts@example.com" required><span class="muted">Use a comma between addresses.</span></label><label>Phone<input name="staff[{{ $index }}][phone]" value="{{ $person['phone'] ?? '' }}" maxlength="50"></label></div></div>@endforeach
</div></section>

<template id="competition-staff-template"><div class="card card-pad competition-staff-row" style="background:var(--surface-subtle, #f8fafc)"><div class="toolbar"><strong class="competition-staff-number">Staff member</strong><button class="button secondary remove-competition-staff" type="button">Remove</button></div><div class="grid two-col"><label>Name<input name="staff[__INDEX__][name]" maxlength="255" required></label><label>Role / position<input name="staff[__INDEX__][role]" maxlength="255" placeholder="e.g. Competition director"></label><label>Email addresses<input name="staff[__INDEX__][emails]" maxlength="2000" placeholder="name@example.com, accounts@example.com" required><span class="muted">Use a comma between addresses.</span></label><label>Phone<input name="staff[__INDEX__][phone]" maxlength="50"></label></div></div></template>

@push('scripts')<script nonce="{{ request()->attributes->get('csp_nonce') }}">(()=>{const rows=document.getElementById('competition-staff-rows');const template=document.getElementById('competition-staff-template');let next={{ count($staffRows) }};const renumber=()=>rows.querySelectorAll('.competition-staff-number').forEach((node,index)=>node.textContent=`Staff member ${index+1}`);document.getElementById('add-competition-staff').addEventListener('click',()=>{rows.insertAdjacentHTML('beforeend',template.innerHTML.replaceAll('__INDEX__',next++));renumber()});rows.addEventListener('click',event=>{if(!event.target.classList.contains('remove-competition-staff'))return;event.target.closest('.competition-staff-row').remove();if(!rows.querySelector('.competition-staff-row'))document.getElementById('add-competition-staff').click();renumber()})})();</script>@endpush
